// TypeScript Version: 4.1

import dsptrf = require( './index' );


// TESTS //

// The function returns a number...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf( 'column-major', 'upper', 4, AP, IPIV ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf( 10, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( true, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( false, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( null, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( void 0, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( [], 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( {}, 'upper', 4, AP, IPIV ); // $ExpectError
	dsptrf( ( x: number ): number => x, 'upper', 4, AP, IPIV ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf( 'column-major', 10, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', true, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', false, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', null, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', void 0, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', [ '1' ], 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', {}, 4, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', ( x: number ): number => x, 4, AP, IPIV ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf( 'column-major', 'upper', '4', AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', true, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', false, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', null, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', void 0, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', [], AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', {}, AP, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', ( x: number ): number => x, AP, IPIV ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a Float64Array...
{
	const IPIV = new Int32Array( 4 );

	dsptrf( 'column-major', 'upper', 4, '5', IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, 5, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, true, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, false, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, null, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, void 0, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, [], IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, {}, IPIV ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, ( x: number ): number => x, IPIV ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not an Int32Array...
{
	const AP = new Float64Array( 10 );

	dsptrf( 'column-major', 'upper', 4, AP, '5' ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, 5 ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, true ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, false ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, null ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, void 0 ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, [] ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, {} ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf(); // $ExpectError
	dsptrf( 'column-major' ); // $ExpectError
	dsptrf( 'column-major', 'upper' ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4 ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP ); // $ExpectError
	dsptrf( 'column-major', 'upper', 4, AP, IPIV, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a string...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf.ndarray( 10, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( true, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( false, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( null, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( void 0, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( [], 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( {}, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( ( x: number ): number => x, 'upper', 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
}

