	dsptrf.ndarray( 'column-major', {}, 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
	dsptrf.ndarray( 'column-major', ( x: number ): number => x, 4, AP, 1, 0, IPIV, 1, 0 ); // $ExpectError
