	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, '0' ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, true ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, false ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, null ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, void 0 ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, [] ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, {} ); // $ExpectError
