// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const AP = new Float64Array( 10 );
	const IPIV = new Int32Array( 4 );

	dsptrf.ndarray(); // $ExpectError
	dsptrf.ndarray( 'column-major' ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper' ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4 ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1 ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0 ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1 ); // $ExpectError
	dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, 0, 10 ); // $ExpectError
}
